  function migratedBlocks(r){
    if(r.liveBlocks&&Array.isArray(r.liveBlocks)&&r.liveBlocks.length) return clone(r.liveBlocks);
    var a=[];
    if(r.text) a.push(Object.assign(defaultBlock('text'),{html:esc(r.text).replace(/\n/g,'<br>')}));
    if(r.files&&r.files.length) a.push(Object.assign(defaultBlock('media'),{files:(r.files||[]).slice(),notes:'Arquivos importados da página antiga.'}));
    if(r.aiText) a.push(Object.assign(defaultBlock('callout'),{text:'🤖 Resposta da IA\n'+r.aiText}));
    if(!a.length) a=[defaultBlock('text')];
    return a;
  }

