  function renderMap(){var box=document.getElementById('avMap');if(!box)return;if(!draft){box.innerHTML='';return}var items=draft.liveBlocks.filter(function(b){return b.type==='heading'||b.type==='gantt'||b.type==='dashboard'||b.type==='cad2d'||b.type==='model3d'||b.type==='slides'||b.type==='code'});box.innerHTML=items.slice(0,24).map(function(b){return '<div class="av-map-link" data-av-goto="'+b.id+'"><span>'+typeInfo(b.type).icon+'</span><span>'+esc((b.text||b.title||typeInfo(b.type).label).slice(0,28))+'</span></div>'}).join('')||'<div style="font-size:8px;color:#7285a7;padding:8px">Os títulos e blocos principais aparecem aqui.</div>'}
  function renderSaveStatus(){var e=document.getElementById('avSaveStatus');if(!e)return;e.textContent=saveState==='salvando'?'Salvando…':'Salvo automaticamente';}

