    canvas.innerHTML='<header class="av-hero"><div class="av-hero-row"><span style="font-size:26px">'+esc(draft.avMeta.emoji||'🪐')+'</span><h1>'+esc(draft.title||'Arquivo Vivo')+'</h1><span class="av-pill">ARQUIVO VIVO</span><span class="av-pill" style="background:#ecfeff;color:#0e7490;border-color:#cffafe">∞ MULTIFERRAMENTA</span><span class="av-pill" style="background:#ecfdf5;color:#047857;border-color:#a7f3d0">🔗 DATA BUS V25</span></div><div class="av-subtitle">Um só arquivo · '+draft.liveBlocks.length+' blocos · atualizado '+fmtDate(draft.updatedAt)+'</div><div class="av-quick-insight">✨ <b>Órbita Infinity</b> — texto, dados, planejamento, criação, código e projetos técnicos convivem no mesmo fluxo e compartilham dados vivos.</div></header><div class="av-blocks" id="avBlocks">'+draft.liveBlocks.map(renderBlock).join('')+'</div>';
    setTimeout(afterRenderBlocks,30);
