  function findBlock(bid){return draft&&draft.liveBlocks.find(function(b){return b.id===bid})}
  function addBlock(type,at){if(!draft){makeNew('Novo Arquivo Vivo','blank')}var b=defaultBlock(type);if(typeof at==='number')draft.liveBlocks.splice(at,0,b);else draft.liveBlocks.push(b);selectedBlock=b.id;saveAndRender();setTimeout(function(){var e=document.getElementById('block-'+b.id);if(e)e.scrollIntoView({behavior:'smooth',block:'center'})},50);return b}
  function saveAndRender(){debounceSave();renderAllInfinity()}
  function afterRenderBlocks(){drawAllCharts();drawAllDiagrams();drawAllCad();drawAll3d();drawAllDesign();hydrateMedia();resumeFocusTimers()}

