  function calcExpr(s){s=String(s||'').replace(/,/g,'.').replace(/√\s*\(([^)]+)\)/g,'Math.sqrt($1)').replace(/√\s*([0-9.]+)/g,'Math.sqrt($1)').replace(/\^/g,'**').replace(/π/gi,'Math.PI');if(!/^[0-9+\-*/().%\s*MathsqrtPIe]+$/.test(s.replace(/Math\.sqrt|Math\.PI/g,''))){}try{return Function('"use strict";return ('+s+')')()}catch(e){return 'Erro'}}
  function runCode(b){var lang=b.language||'javascript',code=b.code||'';if(lang==='json'){try{b.output=JSON.stringify(JSON.parse(code),null,2)}catch(e){b.output='Erro JSON: '+e.message}saveAndRender();return}if(lang==='html'){var w=window.open('','_blank');if(w){w.document.open();w.document.write(code);w.document.close();b.output='Preview aberto em nova janela.'}else b.output='O navegador bloqueou o preview.';saveAndRender();return}if(lang!=='javascript'){b.output='Editor ativo para '+lang+'. Execução local automática está disponível para JavaScript/JSON/HTML. Para '+lang+', use este bloco como IDE e conecte um backend/compilador quando desejar.';saveAndRender();return}var logs=[];try{var fn=Function('console','"use strict";\n'+code);var fake={log:function(){logs.push(Array.prototype.map.call(arguments,function(x){try{return typeof x==='object'?JSON.stringify(x):String(x)}catch(e){return String(x)}}).join(' '))},error:function(){logs.push('ERRO: '+Array.prototype.join.call(arguments,' '))}};var out=fn(fake);if(out!==undefined)logs.push(String(out));b.output=logs.join('\n')||'Executado sem saída.'}catch(e){b.output='Erro: '+e.message}saveAndRender()}

  function runTerminal(b,cmd){cmd=String(cmd||'').trim();if(!cmd)return;var h=b.history||(b.history=[]);h.push('$ '+cmd);var p=cmd.split(/\s+/),op=p.shift().toLowerCase(),rest=p.join(' ');if(op==='help')h.push('Comandos: help, date, clear, calc <expressão>, echo <texto>, stats, blocks, title');else if(op==='date')h.push(new Date().toLocaleString('pt-BR'));else if(op==='clear')b.history=[];else if(op==='calc')h.push(String(calcExpr(rest)));else if(op==='echo')h.push(rest);else if(op==='stats')h.push('Blocos: '+draft.liveBlocks.length+' | Arquivos: '+collectFileIds().length);else if(op==='blocks')h.push(draft.liveBlocks.map(function(x,i){return(i+1)+'. '+typeInfo(x.type).label}).join('\n'));else if(op==='title')h.push(draft.title);else h.push('Comando local não reconhecido. Digite help.');debounceSave();renderCanvas()}

  function deleteBlock(bid){if(!draft)return;var i=draft.liveBlocks.findIndex(function(x){return x.id===bid});if(i<0)return;var b=draft.liveBlocks[i];if(b.type==='media'&&b.files&&b.files.length){/* anexos não são apagados automaticamente: podem estar em outros blocos */}draft.liveBlocks.splice(i,1);selectedBlock=null;if(!draft.liveBlocks.length)draft.liveBlocks.push(defaultBlock('text'));saveAndRender()}
