  function duplicateBlock(bid){var i=draft.liveBlocks.findIndex(function(x){return x.id===bid});if(i<0)return;var x=clone(draft.liveBlocks[i]);x.id=id();if(x.items)x.items=x.items.map(function(a){a.id=id();return a});if(x.nodes)x.nodes=x.nodes.map(function(a){a.id=id();return a});draft.liveBlocks.splice(i+1,0,x);saveAndRender()}
