  draw3d=function(cv,b,preview){var ctx=cv.getContext('2d'),w=cv.width,h=cv.height;ctx.clearRect(0,0,w,h);var grd=ctx.createRadialGradient(w/2,h/2,20,w/2,h/2,w/1.3);grd.addColorStop(0,'#17355e');grd.addColorStop(1,'#07111f');ctx.fillStyle=grd;ctx.fillRect(0,0,w,h);ctx.strokeStyle='rgba(56,189,248,.12)';for(var i=-8;i<=8;i++){ctx.beginPath();var p1=proj(rotPoint({x:i*40,y:-80,z:-320},b.rx,b.ry),cv,b.zoom),p2=proj(rotPoint({x:i*40,y:-80,z:320},b.rx,b.ry),cv,b.zoom);ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke();ctx.beginPath();p1=proj(rotPoint({x:-320,y:-80,z:i*40},b.rx,b.ry),cv,b.zoom);p2=proj(rotPoint({x:320,y:-80,z:i*40},b.rx,b.ry),cv,b.zoom);ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke()}(b.objects||[]).forEach(function(o,idx){o.selected=o.id===b.selectedObjectId;if(o.kind==='cylinder')drawCylinderV23(ctx,cv,o,b,idx);else if(o.kind==='sphere')drawSphereV23(ctx,cv,o,b,idx);else if(o.kind==='wedge')drawWedgeV23(ctx,cv,o,b,idx);else drawBoxV23(ctx,cv,o,b,idx)});if(preview){ctx.save();ctx.strokeStyle='#fbbf24';ctx.fillStyle='rgba(251,191,36,.12)';ctx.setLineDash([8,5]);ctx.lineWidth=2;ctx.strokeRect(Math.min(preview.x1,preview.x2),Math.min(preview.y1,preview.y2),Math.abs(preview.x2-preview.x1),Math.abs(preview.y2-preview.y1));ctx.fillRect(Math.min(preview.x1,preview.x2),Math.min(preview.y1,preview.y2),Math.abs(preview.x2-preview.x1),Math.abs(preview.y2-preview.y1));ctx.restore()}ctx.fillStyle='#94a3b8';ctx.font='12px ui-monospace';ctx.fillText('X '+Math.round(b.rx||0)+'°  Y '+Math.round(b.ry||0)+'°  ZOOM '+Number(b.zoom||1).toFixed(1)+'x · '+String(b.mode||'orbit').toUpperCase(),12,h-14)}
