  drawAllCharts=function(){document.querySelectorAll('canvas.av-chart').forEach(function(cv){var b=findBlock(cv.getAttribute('data-chart'));if(!b)return;ensureBIV24(b);var ctx=cv.getContext('2d'),w=cv.width,h=cv.height,vals=(b.values||[]).map(Number),labels=b.labels||[];ctx.clearRect(0,0,w,h);ctx.strokeStyle='#dce2ec';ctx.lineWidth=1;for(var g=1;g<5;g++){var gy=g*h/5;ctx.beginPath();ctx.moveTo(32,gy);ctx.lineTo(w-10,gy);ctx.stroke()}if(!vals.length)return;var max=Math.max.apply(null,vals.concat([1])),min=Math.min.apply(null,vals.concat([0])),span=max-min||1,base=h-28;function py(v){return base-((v-min)/span)*(h-58)}function px(i){return 38+i*(w-62)/Math.max(1,vals.length-1)}ctx.font='10px Inter';ctx.fillStyle='#64748b';labels.forEach(function(l,i){ctx.fillText(String(l).slice(0,9),px(i)-10,h-8)});if(b.chartType==='bar'){var bw=Math.max(8,(w-70)/Math.max(1,vals.length)*.55);vals.forEach(function(v,i){var y=py(v);ctx.fillStyle='rgba(124,92,255,.78)';ctx.fillRect(px(i)-bw/2,y,bw,base-y);ctx.fillStyle='#475569';ctx.fillText(formatNum(v),px(i)-10,y-5)})}else{ctx.beginPath();vals.forEach(function(v,i){var x=px(i),y=py(v);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});if(b.chartType==='area'){ctx.lineTo(px(vals.length-1),base);ctx.lineTo(px(0),base);ctx.closePath();var gr=ctx.createLinearGradient(0,30,0,base);gr.addColorStop(0,'rgba(124,92,255,.38)');gr.addColorStop(1,'rgba(56,189,248,.04)');ctx.fillStyle=gr;ctx.fill();ctx.beginPath();vals.forEach(function(v,i){var x=px(i),y=py(v);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)})}ctx.strokeStyle='#715cf8';ctx.lineWidth=3;ctx.stroke();vals.forEach(function(v,i){ctx.beginPath();ctx.fillStyle='#38bdf8';ctx.arc(px(i),py(v),4,0,Math.PI*2);ctx.fill()})}})};

