  function keyboardHtml(){return '<div class="av-keyboard" id="avKeyboard"><div class="av-kbd-head"><b>⌨️ ÓRBITA KEYBOARD</b><span id="avKbdTarget">Toque em um campo para digitar</span><div class="av-spacer"></div><button data-av-kbd-mode="abc">ABC</button><button data-av-kbd-mode="num">123</button><button data-av-kbd-mode="math">🧮</button><button data-av-kbd-mode="code">💻</button><button data-av-kbd-mode="cad">📐</button><button data-av-kbd-mode="emoji">😀</button><button data-av-kbd-dock>↕</button><button data-av-kbd-close>✕</button></div><div class="av-kbd-rows" id="avKbdRows"></div></div>'}
  function installKeyboardUI(){if(document.getElementById('avKeyboard'))return;var top=root.querySelector('.av-top-actions');if(top){var bt=document.createElement('button');bt.className='av-btn';bt.setAttribute('data-av-keyboard','');bt.innerHTML='⌨️ Teclado';top.insertBefore(bt,top.firstChild)}var pb=root.querySelector('.av-paperbar');if(pb){var kb=document.createElement('button');kb.className='av-mini-btn';kb.setAttribute('data-av-keyboard','');kb.textContent='⌨️ Teclado';pb.appendChild(kb)}root.insertAdjacentHTML('beforeend',keyboardHtml());renderKeyboardKeys()}
  function renderKeyboardKeys(){var box=document.getElementById('avKbdRows');if(!box)return;var rows=V24_KEYS[V24_KBD.mode]||V24_KEYS.abc;box.innerHTML=rows.map(function(row){return '<div class="av-kbd-row">'+row.map(function(k){var show=(V24_KBD.shift&&V24_KBD.mode==='abc'&&k.length===1)?k.toUpperCase():k;return '<button data-av-kbd-key="'+esc(k)+'" class="'+(['Espaço','Enter','⌫','⇧'].indexOf(k)>=0?'special':'')+'">'+esc(show)+'</button>'}).join('')+'</div>'}).join('')}
