  function editableTarget(el){return el&&((/^(INPUT|TEXTAREA)$/.test(el.tagName)&&!['button','checkbox','radio','color','range'].includes(el.type))||el.isContentEditable)}
  function kbdInsert(text){var el=V24_KBD.target;if(!editableTarget(el)){toast('Toque primeiro onde deseja digitar.');return}if(V24_KBD.shift&&V24_KBD.mode==='abc'&&text.length===1){text=text.toUpperCase();V24_KBD.shift=false;renderKeyboardKeys()}if(el.isContentEditable){el.focus();var sel=window.getSelection();if(V24_KBD.range&&sel){try{sel.removeAllRanges();sel.addRange(V24_KBD.range)}catch(e){}}try{document.execCommand('insertText',false,text)}catch(e){el.textContent+=text}el.dispatchEvent(new Event('input',{bubbles:true}));try{V24_KBD.range=sel.getRangeAt(0).cloneRange()}catch(e){}}else{el.focus();var a=el.selectionStart==null?el.value.length:el.selectionStart,z=el.selectionEnd==null?a:el.selectionEnd;el.value=el.value.slice(0,a)+text+el.value.slice(z);el.selectionStart=el.selectionEnd=a+text.length;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))}}
  function kbdBackspace(){var el=V24_KBD.target;if(!editableTarget(el))return;if(el.isContentEditable){el.focus();var sel=window.getSelection();if(V24_KBD.range&&sel){try{sel.removeAllRanges();sel.addRange(V24_KBD.range)}catch(e){}}document.execCommand('delete');el.dispatchEvent(new Event('input',{bubbles:true}));try{V24_KBD.range=sel.getRangeAt(0).cloneRange()}catch(e){}}else{var a=el.selectionStart||0,z=el.selectionEnd||a;if(a!==z){el.value=el.value.slice(0,a)+el.value.slice(z)}else if(a>0){el.value=el.value.slice(0,a-1)+el.value.slice(a);a--}el.selectionStart=el.selectionEnd=a;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))}}
  document.addEventListener('focusin',function(e){if(root.contains(e.target)&&editableTarget(e.target)&&!e.target.closest('#avKeyboard')){V24_KBD.target=e.target;var t=document.getElementById('avKbdTarget');if(t)t.textContent=e.target.getAttribute('data-cell')||e.target.placeholder||e.target.tagName}});
  document.addEventListener('selectionchange',function(){var el=document.activeElement;if(el&&root.contains(el)&&el.isContentEditable){V24_KBD.target=el;var sel=window.getSelection();if(sel&&sel.rangeCount)try{V24_KBD.range=sel.getRangeAt(0).cloneRange()}catch(e){}}});

